// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.BufferedReader;
import java.io.File;
import java.io.InputStreamReader;
import java.lang.reflect.Modifier;
import java.net.JarURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Enumeration;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.jar.JarEntry;
import java.util.jar.JarFile;

import org.eclipse.rdf4j.query.algebra.ValueExpr;
import org.junit.jupiter.api.Test;

/**
 * The expression-coverage census: every concrete {@link ValueExpr} subclass of the algebra model and every function
 * implementation registered through the generic evaluator's SPI service file must carry an explicit disposition in
 * {@link LmdbNativeExpressionCensus}. This test scans the algebra package and the SPI resources on the classpath, so a
 * new expression node or built-in function fails the build here until someone classifies it — the expression compilers
 * decline silently with {@code return null}, and this census is the enforced inventory of those declines.
 */
public class LmdbNativeExpressionCensusTest {

	private static final String PACKAGE_PATH = "org/eclipse/rdf4j/query/algebra";
	private static final String FUNCTION_SERVICE = "META-INF/services/org.eclipse.rdf4j.query.algebra.evaluation.function.Function";

	@Test
	public void everyConcreteValueExprIsClassified() throws Exception {
		List<Class<? extends ValueExpr>> concrete = concreteValueExprClasses();
		assertThat(concrete)
				.as("the classpath scan must find the expression nodes (scan mechanism sanity)")
				.hasSizeGreaterThan(30);
		List<String> unclassified = new ArrayList<>();
		for (Class<? extends ValueExpr> expressionClass : concrete) {
			if (LmdbNativeExpressionCensus.classify(expressionClass) == null) {
				unclassified.add(expressionClass.getName());
			}
		}
		assertThat(unclassified)
				.as("every concrete ValueExpr must have an explicit census disposition "
						+ "(add the new node to LmdbNativeExpressionCensus — usually as GENERIC until promoted)")
				.isEmpty();
	}

	@Test
	public void everyRegisteredFunctionIsClassified() throws Exception {
		Set<String> implementations = registeredFunctionImplementations();
		assertThat(implementations)
				.as("the SPI scan must find the registered functions (scan mechanism sanity)")
				.hasSizeGreaterThan(50);
		List<String> unclassified = new ArrayList<>();
		for (String implementation : implementations) {
			if (LmdbNativeExpressionCensus.classifyFunction(implementation) == null) {
				unclassified.add(implementation);
			}
		}
		assertThat(unclassified)
				.as("every SPI-registered function must have an explicit census disposition "
						+ "(add the new function to LmdbNativeExpressionCensus — usually as GENERIC until promoted)")
				.isEmpty();
	}

	private Set<String> registeredFunctionImplementations() throws Exception {
		Set<String> implementations = new LinkedHashSet<>();
		Enumeration<URL> resources = ValueExpr.class.getClassLoader().getResources(FUNCTION_SERVICE);
		while (resources.hasMoreElements()) {
			URL resource = resources.nextElement();
			try (BufferedReader reader = new BufferedReader(
					new InputStreamReader(resource.openStream(), StandardCharsets.UTF_8))) {
				String line;
				while ((line = reader.readLine()) != null) {
					String name = line.trim();
					int comment = name.indexOf('#');
					if (comment >= 0) {
						name = name.substring(0, comment).trim();
					}
					if (!name.isEmpty()) {
						implementations.add(name);
					}
				}
			}
		}
		return implementations;
	}

	private List<Class<? extends ValueExpr>> concreteValueExprClasses() throws Exception {
		ClassLoader loader = ValueExpr.class.getClassLoader();
		List<String> classNames = new ArrayList<>();
		Enumeration<URL> roots = loader.getResources(PACKAGE_PATH);
		while (roots.hasMoreElements()) {
			URL root = roots.nextElement();
			if ("jar".equals(root.getProtocol())) {
				JarURLConnection connection = (JarURLConnection) root.openConnection();
				try (JarFile jar = new JarFile(connection.getJarFileURL().getPath())) {
					Enumeration<JarEntry> entries = jar.entries();
					while (entries.hasMoreElements()) {
						String name = entries.nextElement().getName();
						if (name.startsWith(PACKAGE_PATH + "/") && name.endsWith(".class")
								&& !name.substring(PACKAGE_PATH.length() + 1).contains("/")) {
							classNames.add(name.substring(0, name.length() - ".class".length()).replace('/', '.'));
						}
					}
				}
			} else if ("file".equals(root.getProtocol())) {
				File dir = new File(root.toURI());
				File[] files = dir.listFiles((d, name) -> name.endsWith(".class"));
				if (files != null) {
					for (File file : files) {
						classNames.add(PACKAGE_PATH.replace('/', '.') + "."
								+ file.getName().substring(0, file.getName().length() - ".class".length()));
					}
				}
			}
		}
		List<Class<? extends ValueExpr>> concrete = new ArrayList<>();
		for (String className : classNames) {
			if (className.contains("$")) {
				continue;
			}
			Class<?> candidate = Class.forName(className, false, loader);
			if (ValueExpr.class.isAssignableFrom(candidate) && !candidate.isInterface()
					&& !Modifier.isAbstract(candidate.getModifiers())) {
				concrete.add(candidate.asSubclass(ValueExpr.class));
			}
		}
		return concrete;
	}
}
